const targets = Array.from(game.user.targets);
if (!targets.length) return ui.notifications.warn("Please target at least one token!");

// V13 Modern Input Dialog
const data = await foundry.applications.api.DialogV2.input({
  window: { title: "Edit_SP" },
  content: `
    <div class="form-group">
      <label>Edit SPIRIT</label>
      <div class="form-fields">
        <!-- Changed to text to allow math strings -->
        <input type="text" name="spiritAdjustment" placeholder="0" autofocus>
      </div>
    </div>`,
  ok: { label: "Apply", icon: "fa-solid fa-burst" }
});

// Check for empty or cancelled input
if (!data || !data.spiritAdjustment) return;

// --- LAZY INPUT LOGIC ---
const matches = data.spiritAdjustment.match(/[+-]?\d+/g);
if (!matches) return ui.notifications.error("No valid numbers found.");
const totalAdjustment = matches.reduce((acc, num) => acc + parseInt(num), 0);
// ------------------------

for (let token of targets) {
  const actor = token.actor;
  const spiritPath = "system.spirit.value";
  const spiritMax = "system.spirit.max";
  const currentSpirit = foundry.utils.getProperty(actor, spiritPath);
  const maxSpirit = foundry.utils.getProperty(actor, spiritMax);

  if (currentSpirit === undefined || maxSpirit === undefined) {
    console.warn(`Plume | ${token.name} does not have spirit defined.`);
    continue;
  }

  // Calculate new Spirit (Clamped -999 to Max)
  const newSpirit = Math.clamp(currentSpirit + totalAdjustment, -999, maxSpirit);
  await actor.update({ [spiritPath]: newSpirit });

  // Simple Chat Feedback
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ token: token.document }),
    content: `
      <div class="dice-roll">
        <div class="dice-result">
          <div class="dice-total" style="color: #000000; border: 1px solid #000;"> 
            ${totalAdjustment >= 0 ? "+" : ""}${totalAdjustment} SP 
          </div>
          <div style="font-size: 1em; text-align: center;">
            ${currentSpirit} &rarr; ${newSpirit}
          </div>
        </div>
      </div>`,
    sound: CONFIG.sounds.dice
  });
}
